var i=`0537-saltah`;var t=`world-0537`;var a=`YE`;var o=`western-asia`;var s=4;var r=69;var g={en:`Saltah`,ua:`Сальта`};var l={en:`A traditional dish from Yemen, centered on yellow onion, tomato, garlic, lamb. A measured home-kitchen version organized by cooking step.`,ua:`Традиційна страва кухні країни Ємен. Основні складники: жовта цибуля, помідор, часник, ягнятина. Домашній варіант із кількостями продуктів за етапами приготування.`};var d=[{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 10 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 10 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:10,i:[[`yellow-onion`,180,`g`],[`tomato`,310,`g`],[`garlic`,4,`clove`],[`sunflower-oil`,45,`ml`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 45 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 45 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:45,i:[[`lamb`,600,`g`],[`water`,800,`ml`],[`ground-cumin`,5,`g`],[`ground-fenugreek`,5,`g`]]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:10,i:[[`chicken-egg`,2,`pcs`],[`cilantro`,50,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:4,i:[[`pita-bread`,4,`pcs`]]}];var m={slug:i,id:t,country:`YE`,region:o,servings:4,minutes:69,title:g,text:l,steps:d};export{a as country,m as default,t as id,r as minutes,o as region,s as servings,i as slug,d as steps,l as text,g as title};